import{_ as e,H as p,f as s,i as o}from"./chunks/framework.BH2BK_3i.js";const b=JSON.parse('{"title":"结束语 | 第一阶段课程结尾展望","description":"","frontmatter":{},"headers":[],"relativePath":"Rust实战·手写下一代云原生消息队列/结束语｜第一阶段课程结尾展望.md","filePath":"Rust实战·手写下一代云原生消息队列/结束语｜第一阶段课程结尾展望.md","lastUpdated":1795533810000}'),i={name:"Rust实战·手写下一代云原生消息队列/结束语｜第一阶段课程结尾展望.md"};function l(a,t,r,u,n,E){return p(),s("div",null,[...t[0]||(t[0]=[o('<h1 id="结束语-第一阶段课程结尾展望" tabindex="-1">结束语 | 第一阶段课程结尾展望 <a class="header-anchor" href="#结束语-第一阶段课程结尾展望" aria-label="Permalink to &quot;结束语 | 第一阶段课程结尾展望&quot;">​</a></h1><ul><li>本课程为精品小课，不标配音频</li></ul><p>你好，我是文强。</p><p>到今天我们就正式结束这次课程了，在这门课程中我们基于 gRPC + RocksDB + Raft 构建了一个元数据服务集群。</p><p>从内容来看，每节课涉及的内容很多，包括但不限于 Rust 语言本身的知识点，还有比如分布式系统、网络、存储相关的内容。所以学习这个课程的过程可能会让你觉得有点吃力。不过，吃力也是合理的，内容知识点确实很多。</p><p>因此，这里我想再分享一下我对这门课程的期待和定位。在做课程设计的时候，我就明确了，我不想教你那种很基础的官方知识点的“翻译”，而是想教给你一些在平时很难获得的东西，在我看来可以叫做“经验”。</p><p>为抓手，带你去做一个真正具有工业化水准的基础软件。希望在这个课程中你可以获得：</p><ol><li><p>学好、学会 Rust 这个语言本身。</p></li><li><p>知道如何开发实现一个分布式存储系统。</p></li><li><p>参与写一个具有工业化水准的开源基础软件的经验。</p></li><li><p>学会思考，技术上为什么会这么做，为什么不那么做。</p></li></ol><p>当然，一分耕耘、一份收获，想从这个课程中获得更多的“经验”，就需要你更加投入，去理解课程、去理解代码、去旁征博引地学习更多内容，去交流群讨论和学习等等。编码、学习本身是一件很辛苦的过程。当你获得某个技能的过程越艰难，从某种程度来说你的竞争力就越强。</p><p>另外，在本次课程中，你会发现我们有两个项目《robustmq-geek》和《robustmq》。robustmq-geek 是课程配套的可运行的 Demo 示例，robustmq 是我们在社区推进的消息队列领域的开源项目。你可以理解 robustmq-geek 是开源项目 robustmq 的教学简化版，你也可以理解 robustmq 是 robustmq-geek 的工业化版本。</p><p>从课程设计的角度，我的初衷是希望你学会了本次课程后，能够去参与 robustmq 的开发。从而给你提供一个梯度，从简单到复杂，从示例项目到开源的工业化的基础软件项目，带你更好地去获得“经验”。</p><p>以终为始，为了告诉你我的系列课程最终会带你做成一个什么样子的基础软件。下面我来简单介绍一下 RobustMQ。</p><p>RobustMQ 的定位是基于 Rust 构建兼容多种主流消息队列协议、架构上具备完整 Serveless能力的下一代高性能云原生融合型消息队列。我希望把 RobustMQ 打造成下一个消息队列领域的 Apache 顶级项目。</p><p>它的整体架构图如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Rust%E5%AE%9E%E6%88%98%C2%B7%E6%89%8B%E5%86%99%E4%B8%8B%E4%B8%80%E4%BB%A3%E4%BA%91%E5%8E%9F%E7%94%9F%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%97/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Rust%E5%AE%9E%E6%88%98%C2%B7%E6%89%8B%E5%86%99%E4%B8%8B%E4%B8%80%E4%BB%A3%E4%BA%91%E5%8E%9F%E7%94%9F%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%97/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/1.png" alt=""></a></p><p>从设计的角度看，RobustMQ 是一个典型的分布式分层架构，包含计算层、存储层、调度层分离等。具体由控制层（Placement Center）、计算层（Multi-protocol computing layer）、存储适配层（Storage Adapter Layer）、独立的远端存储层（Standalone storage engine）四个部分组成。每一层都具备快速扩缩容能力，从而达到整个系统具备完整的 Serverless 能力。</p><p>因此它具备以下特点：</p><ol><li><p>100% Rust：完全基于 Rust 语言实现的消息队列引擎。</p></li><li><p>多协议：支持 MQTT 3.1/3.1.1/5.0、AMQP、Kafka Protocol、RocketMQRemoting/gRPC、OpenMessing、JNS、SQS 等主流消息协议。</p></li><li><p>分层架构：计算、存储、调度独立的三层架构，每层均具备集群化部署、快速水平扩缩容的能力。</p></li><li><p>插件式存储：独立插件式的存储层实现，可根据需要选择合适的存储层。兼容传统和云原生架构，支持云、IDC 多种部署形态。</p></li><li><p>高内聚架构：提供内置的元数据存储组件（Placement Center）和分布式存储服务（RobustMQ Journal Server），具备快速、简单、内聚的部署能力。</p></li><li><p>功能丰富：支持顺序消息、死信消息、事务消息、幂等消息、延时消息等丰富的消息队列功能。</p></li></ol><p>从项目愿景和技术架构来看，RobustMQ 是一个非常大的工程，非常有技术含量。如果你用心参与和学习，在我看来这个工程肯定可以给你带来成长，甚至是无与伦比的竞争力。</p><p>这里给你分享几个 RobustMQ 的资料，以便让你更好地了解 RobustMQ。</p><ol><li><p>《RobustMQ 魔法入门手册》</p></li><li><p>《RobustMQ 官网》</p></li><li><p>《RobustMQ 官方中文文档》</p></li><li><p>《RobustMQ GitHub 项目》</p></li><li><p>《RobustMQ 贡献指南》</p></li><li><p>Rust Conf 2024 分享 PPT：《RobustMQ - 下一代高性能云原生融合型消息队列》</p></li><li><p>Rust Conf 2024 分享视频：《RobustMQ - 下一代高性能云原生融合型消息队列》</p></li></ol><p>课程的最后，祝愿你和我一样能在学习的过程中获得更多的踏实感，希望我们一起在这个内卷的环境中愈发从容！</p>',22)])])}const R=e(i,[["render",l]]);export{b as __pageData,R as default};
